import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import UploadForm from '@/components/upload/UploadForm.vue';
import { mapGetters } from 'vuex';
import { fileManager } from '@/utils/fileManager';
import fetchWithAuth from '@/utils/fetchWithAuth';
import { ElMessage } from 'element-plus';
export default {
  name: 'UploadHome',
  components: {
    UploadForm
  },
  data() {
    return {
      tableData: [],
      Number: 0,
      loading: false,
      selectedUrlForm: 'url',
      customerCompress: true,
      compressQuality: 4,
      compressBar: 5,
      serverCompress: true,
      uploadChannel: 'telegram',
      channelName: '',
      uploadNameType: 'default',
      customUrlPrefix: '',
      useCustomUrl: 'false',
      autoRetry: true,
      uploadMethod: 'default',
      uploadFolder: '',
      convertToWebp: false
    };
  },
  computed: {
    ...mapGetters(['userConfig', 'uploadCopyUrlForm', 'compressConfig', 'storeUploadChannel', 'storeChannelName', 'storeUploadNameType', 'customUrlSettings', 'storeAutoRetry', 'storeUploadMethod', 'storeUploadFolder']),
    urlPrefix() {
      return this.userConfig?.urlPrefix || `${window.location.protocol}//${window.location.host}/file/`;
    }
  },
  methods: {
    async handleUploadSuccess() {
      await this.refreshGallery();
    },
    async refreshGallery() {
      this.loading = true;
      try {
        const success = await fileManager.refreshFileList('/', '', '', '', {}, false);
        if (success) {
          const data = fileManager.getLocalFileList();
          this.tableData = (data.files || []).filter(f => !f.isFolder);
          this.Number = this.tableData.length;
        }
      } catch (error) {
        console.error('获取图库失败', error);
      } finally {
        this.loading = false;
      }
    },
    getFileLink(filename) {
      return process.env.NODE_ENV === 'production' ? `/file/${filename}` : `/api/file/${filename}`;
    },
    quickCopy(filename) {
      const url = window.location.origin + this.getFileLink(filename);
      navigator.clipboard.writeText(url).then(() => {
        ElMessage.success('链接已复制');
      }).catch(() => ElMessage.error('复制失败'));
    },
    quickDelete(index, key) {
      fetchWithAuth(`/api/manage/delete/${key}?folder=false`, {
        method: 'GET'
      }).then(response => {
        if (response.ok) {
          this.tableData.splice(index, 1);
          fileManager.removeFile(key);
          this.Number--;
          ElMessage.success('图片已删除');
        } else {
          ElMessage.error('删除失败');
        }
      });
    }
  },
  mounted() {
    this.selectedUrlForm = this.uploadCopyUrlForm || 'url';
    this.uploadChannel = this.storeUploadChannel || 'telegram';
    this.uploadMethod = this.storeUploadMethod || 'default';
    this.uploadFolder = this.storeUploadFolder || '';

    // 延迟拉取数据，防止阻塞渲染
    setTimeout(() => {
      this.refreshGallery();
    }, 300);
  }
};